INSERT INTO `cr_eval_algorithm` VALUES (1,'992c712d877c31529833a24d6ef6a347','内存使用率',NULL,0,2,0,'import json\n\n\ndef solution(data, other_arguments):\n    \"\"\"\n    格式化算法模板\n    :param data: 探针采集数据, jsonString\n    :param other_arguments: List[int, str, bool], 可配置参数列表, 长度、索引一致\n    :return: 格式化结果字符串\n    \"\"\"\n    _data = json.loads(data)\n    return int(_data.get(\"memoryPercent\"))\n','[]',0,'3f655d87112f4ae094bbaf70830e20aa','2020-06-23 18:37:15','2020-06-23 19:07:11'),(2,'ac09d98b4025d967e55bc684ae4f9560','磁盘使用率',NULL,0,2,0,'import json\n\n\ndef solution(data, other_arguments):\n    \"\"\"\n    格式化算法模板\n    :param data: 探针采集数据, jsonString\n    :param other_arguments: List[int, str, bool], 可配置参数列表, 长度、索引一致\n    :return: 格式化结果字符串\n    \"\"\"\n    _data = json.loads(data)\n    return int(_data.get(\"diskPercent\"))\n','[]',0,'3f655d87112f4ae094bbaf70830e20aa','2020-06-23 18:40:54','2020-06-23 19:07:29'),(3,'bb23247a834e0b34c225cd7e9b612a7c','CPU使用率',NULL,0,2,0,'import json\n\n\ndef solution(data, other_arguments):\n    \"\"\"\n    格式化算法模板\n    :param data: 探针采集数据, jsonString\n    :param other_arguments: List[int, str, bool], 可配置参数列表, 长度、索引一致\n    :return: 格式化结果字符串\n    \"\"\"\n    _data = json.loads(data)\n    return int(_data.get(\"cpuPercent\"))\n','[]',0,'3f655d87112f4ae094bbaf70830e20aa','2020-06-23 18:41:40','2020-06-23 19:07:40'),(4,'4c2903a078ce12a7adb853b960e3ec04','JSON属性获取',NULL,0,2,0,'def solution(data: str, other_arguments) -> str:\n    \"\"\"\n    格式化算法模板\n    :param data: 探针采集数据, jsonString\n    :param other_arguments: List[int, str, bool], 可配置参数列表, 长度、索引一致\n    :return: 格式化结果字符串\n    \"\"\"\n    import json\n    _data = json.loads(data)\n    return _data.get(other_arguments[0])\n','[{\"defaultValue\":\"key\",\"desc\":\"JSON对象KEY\",\"paramName\":\"属性\",\"paramType\":\"1\"}]',1,'3f655d87112f4ae094bbaf70830e20aa','2020-06-23 18:42:41','2020-06-23 19:11:41'),(5,'df17fa0f5f52880128d079ed14f98eb7','绝对值范围',NULL,0,3,0,'from typing import Dict, List\n\n\ndef solution(data, other_arguments):\n    \"\"\"\n    模型匹配算法模板\n    :param data: {\n         \"baseTime\": #{时间戳 ms}: int,\n         \"data\": [\n           {\n                 \"t\": #{baseTime偏移量 ms}: int,\n                 \"v\": #{格式化算法返回值}: str\n           },\n           { }...\n       ]\n    }\n    :param other_arguments: List[int, str, bool], 可配置参数列表, 长度、索引一致\n    :return: 匹配结果. 为[0, 1, 1, ...], 0-未匹配, 1-匹配. 长度、索引应与data[\"data\"]中元素一致\n    \"\"\"\n    results = []\n    _data: List[Dict] = data.get(\"data\")\n\n    for _item in _data:\n        results.append(1 if other_arguments[0] <= int(_item.get(\"v\")) <= other_arguments[1] else 0)\n\n    return results\n','[{\"defaultValue\":\"0\",\"desc\":\"\",\"paramName\":\"Min\",\"paramType\":\"0\"},{\"defaultValue\":\"100\",\"desc\":\"\",\"paramName\":\"Max\",\"paramType\":\"0\"}]',2,'3f655d87112f4ae094bbaf70830e20aa','2020-06-23 18:44:37','2020-06-23 19:21:24'),(6,'34151eee3021f4cc8d9642a5fe67afb5','绝对值过大',NULL,0,3,0,'\ndef solution(data, other_arguments):\n    \"\"\"\n    模型匹配算法模板\n    :param data: {\n         \"baseTime\": #{时间戳 ms}: int,\n         \"data\": [\n           {\n                 \"t\": #{baseTime偏移量 ms}: int,\n                 \"v\": #{格式化算法返回值}: str\n           },\n           { }...\n       ]\n    }\n    :param other_arguments: List[int, str, bool], 可配置参数列表, 长度、索引一致\n    :return: 匹配结果. 为[0, 1, 1, ...], 0-未匹配, 1-匹配. 长度、索引应与data[\"data\"]中元素一致\n    \"\"\"\n    results = []\n    for i in data.get(\"data\"):\n        if int(i.get(\"v\")) >= other_arguments[0]:\n            results.append(1)\n        else:\n            results.append(0)\n\n    return results','[{\"defaultValue\":\"60\",\"desc\":\"幅度\",\"paramName\":\"幅度\",\"paramType\":\"0\"}]',1,'3f655d87112f4ae094bbaf70830e20aa','2020-06-23 18:45:32','2020-06-23 19:21:35'),(7,'3f686ec6badc22fd8bd8a4ca1dbd8a95','绝对值过小',NULL,0,3,0,'\ndef solution(data, other_arguments):\n    \"\"\"\n    模型匹配算法模板\n    :param data: {\n         \"baseTime\": #{时间戳 ms}: int,\n         \"data\": [\n           {\n                 \"t\": #{baseTime偏移量 ms}: int,\n                 \"v\": #{格式化算法返回值}: str\n           },\n           { }...\n       ]\n    }\n    :param other_arguments: List[int, str, bool], 可配置参数列表, 长度、索引一致\n    :return: 匹配结果. 为[0, 1, 1, ...], 0-未匹配, 1-匹配. 长度、索引应与data[\"data\"]中元素一致\n    \"\"\"\n    results = []\n    for i in data.get(\"data\"):\n        if int(i.get(\"v\")) <= other_arguments[0]:\n            results.append(1)\n        else:\n            results.append(0)\n\n    return results','[{\"defaultValue\":\"60\",\"desc\":\"幅度\",\"paramName\":\"幅度\",\"paramType\":\"0\"}]',1,'3f655d87112f4ae094bbaf70830e20aa','2020-06-23 18:46:07','2020-06-23 19:21:50'),(8,'cb74b797f4dc095f344bb3deb6584373','关键字匹配',NULL,0,3,0,'from typing import Dict, List\n\n\ndef solution(data, other_arguments):\n    \"\"\"\n    模型匹配算法模板\n    :param data: {\n         \"baseTime\": #{时间戳 ms}: int,\n         \"data\": [\n           {\n                 \"t\": #{baseTime偏移量 ms}: int,\n                 \"v\": #{格式化算法返回值}: str\n           },\n           { }...\n       ]\n    }\n    :param other_arguments: List[int, str, bool], 可配置参数列表, 长度、索引一致\n    :return: 匹配结果. 为[0, 1, 1, ...], 0-未匹配, 1-匹配. 长度、索引应与data[\"data\"]中元素一致\n    \"\"\"\n    results = []\n    _data: List[Dict] = data.get(\"data\")\n\n    for _item in _data:\n        if not isinstance( _item.get(\"v\"), str):\n            results.append(0)\n            continue\n        results.append(1 if other_arguments[0] in _item.get(\"v\") else 0)\n\n    return results\n','[{\"defaultValue\":\"Keyword\",\"desc\":\"匹配关键字\",\"paramName\":\"关键字\\t\",\"paramType\":\"1\"}]',1,'3f655d87112f4ae094bbaf70830e20aa','2020-06-23 18:47:38','2020-06-23 19:22:04'),(9,'b4e35ea158219701083147285c50f968','关键字非匹配',NULL,0,3,0,'from typing import Dict, List\n\n\ndef solution(data, other_arguments):\n    \"\"\"\n    模型匹配算法模板\n    :param data: {\n         \"baseTime\": #{时间戳 ms}: int,\n         \"data\": [\n           {\n                 \"t\": #{baseTime偏移量 ms}: int,\n                 \"v\": #{格式化算法返回值}: str\n           },\n           { }...\n       ]\n    }\n    :param other_arguments: List[int, str, bool], 可配置参数列表, 长度、索引一致\n    :return: 匹配结果. 为[0, 1, 1, ...], 0-未匹配, 1-匹配. 长度、索引应与data[\"data\"]中元素一致\n    \"\"\"\n    results = []\n    _data: List[Dict] = data.get(\"data\")\n\n    for _item in _data:\n        if not isinstance( _item.get(\"v\"), str):\n            results.append(0)\n            continue\n        results.append(1 if other_arguments[0] not in _item.get(\"v\") else 0)\n\n    return results\n','[{\"defaultValue\":\"Keyword\",\"desc\":\"\",\"paramName\":\"关键字\",\"paramType\":\"1\"}]',1,'3f655d87112f4ae094bbaf70830e20aa','2020-06-23 18:48:36','2020-06-23 19:22:12'),(10,'6813e38d6eb0195230626e1e09902a71','高于平均值',NULL,0,3,0,'from typing import List\n\n\ndef solution(data, other_arguments) -> List[int]:\n    \"\"\"\n    模型匹配算法模板\n    :param data: {\n         \"baseTime\": #{时间戳 ms}: int,\n         \"data\": [\n           {\n                 \"t\": #{baseTime偏移量 ms}: int,\n                 \"v\": #{格式化算法返回值}: str\n           },\n           { }...\n       ]\n    }\n    :param other_arguments: List[int, str, bool], 可配置参数列表, 长度、索引一致\n    :return: 匹配结果. 为[0, 1, 1, ...], 0-未匹配, 1-匹配. 长度、索引应与data[\"data\"]中元素一致\n    \"\"\"\n    results = []\n    _data = data.get(\"data\")\n    values = [int(_item[\"v\"]) for _item in _data]\n    _range = other_arguments[0] / 100\n\n    avg = sum(values) / len(values)\n    score = int(avg * _range)\n    for v in values:\n        if v - score >= avg:\n            results.append(1)\n        else:\n            results.append(0)\n\n    return results','[{\"defaultValue\":\"50\",\"desc\":\"\",\"paramName\":\"幅度\",\"paramType\":\"0\"}]',1,'3f655d87112f4ae094bbaf70830e20aa','2020-06-23 18:50:44','2020-06-23 18:50:44'),(11,'f1e4ccd6698aa7f4dfb9d07e97fdf7b6','匹配次数绝对值衰减',NULL,0,1,0,'\n\ndef solution(data, other_arguments):\n    \"\"\"\n    评分算法模板\n    :param data: {\n         \"baseTime\": #{时间戳}: ms,\n         \"data\": [\n           {\n                 \"t\": #{baseTime偏移量 ms}: int,\n                 \"v\": #{格式化算法返回值}: str,\n                 \"m\": #{是否被匹配, 0|1}: int\n           },\n          { }...\n        ]\n   }\n   :param other_arguments: List[int, str, bool], 可配置参数列表, 长度、索引一致\n   :return: 评分结果, 0~100\n    \"\"\"\n    result = 100 - len([i.get(\"v\") for i in data.get(\"data\") if i.get(\"m\")]) * other_arguments[0]\n    return max(0, result)\n','[{\"defaultValue\":\"5\",\"desc\":\"衰减幅度\",\"paramName\":\"幅度\",\"paramType\":\"0\"}]',1,'3f655d87112f4ae094bbaf70830e20aa','2020-06-23 18:55:46','2020-06-23 19:22:44'),(12,'6c45132ff7b193a160a70ca33d0e6f20','匹配次数百分比衰减',NULL,0,1,0,'\n\ndef solution(data, other_arguments):\n    \"\"\"\n    评分算法模板\n    :param data: {\n         \"baseTime\": #{时间戳}: ms,\n         \"data\": [\n           {\n                 \"t\": #{baseTime偏移量 ms}: int,\n                 \"v\": #{格式化算法返回值}: str,\n                 \"m\": #{是否被匹配, 0|1}: int\n           },\n          { }...\n        ]\n   }\n   :param other_arguments: List[int, str, bool], 可配置参数列表, 长度、索引一致\n   :return: 评分结果, 0~100\n    \"\"\"\n    result = 100\n    matched_count = len([i.get(\"v\") for i in data.get(\"data\") if i.get(\"m\")])\n\n    for i in range(matched_count):\n        result = (100 - other_arguments[0]) / 100 * result\n\n    return int(result)\n','[{\"defaultValue\":\"5\",\"desc\":\"衰减幅度\",\"paramName\":\"幅度\",\"paramType\":\"0\"}]',1,'3f655d87112f4ae094bbaf70830e20aa','2020-06-23 18:56:33','2020-06-23 19:24:38'),(13,'fdf0b59f18c473622d8182e7cd94bb87','匹配次数绝对值增长',NULL,0,1,0,'\n\ndef solution(data, other_arguments):\n    \"\"\"\n    评分算法模板\n    :param data: {\n         \"baseTime\": #{时间戳}: ms,\n         \"data\": [\n           {\n                 \"t\": #{baseTime偏移量 ms}: int,\n                 \"v\": #{格式化算法返回值}: str,\n                 \"m\": #{是否被匹配, 0|1}: int\n           },\n          { }...\n        ]\n   }\n   :param other_arguments: List[int, str, bool], 可配置参数列表, 长度、索引一致\n   :return: 评分结果, 0~100\n    \"\"\"\n    result = len([i.get(\"v\") for i in data.get(\"data\") if i.get(\"m\")]) * other_arguments[0]\n    return min(100, result) if result > 100 else result','[{\"defaultValue\":\"5\",\"desc\":\"增长幅度\",\"paramName\":\"幅度\",\"paramType\":\"0\"}]',1,'3f655d87112f4ae094bbaf70830e20aa','2020-06-23 18:57:48','2020-06-23 19:24:47'),(14,'f417010759937eedd2994f9755228168','计算最高分',NULL,0,4,0,'def solution(data, other_arguments):\n    \"\"\"\n    聚合算法模板\n    :param data: 包含元素均为0~100 int\n    :param other_arguments: List[int, str, bool], 可配置参数列表, 长度、索引一致\n    :return: 聚合算法结果, 0~100\n    \"\"\"\n    return max([int(i) for i in data])','[]',0,'3f655d87112f4ae094bbaf70830e20aa','2020-06-23 18:59:33','2020-06-23 19:25:01'),(15,'8dd5037ab80e6bdc2451e20bd161c916','计算最低分',NULL,0,4,0,'def solution(data, other_arguments):\n    \"\"\"\n    聚合算法模板\n    :param data: 包含元素均为0~100 int\n    :param other_arguments: List[int, str, bool], 可配置参数列表, 长度、索引一致\n    :return: 聚合算法结果, 0~100\n    \"\"\"\n    return min([int(i) for i in data])','[]',0,'3f655d87112f4ae094bbaf70830e20aa','2020-06-23 19:00:28','2020-06-23 19:25:12'),(16,'86983b7bad3567cc2e36db0c1f7d3cd9','算术平均',NULL,0,4,0,'def solution(data, other_arguments):\n    \"\"\"\n    聚合算法模板\n    :param data: 包含元素均为0~100 int\n    :param other_arguments: List[int, str, bool], 可配置参数列表, 长度、索引一致\n    :return: 聚合算法结果, 0~100\n    \"\"\"\n    variables = [int(i) for i in data]\n    return sum(variables) / len(variables)\n','[]',0,'3f655d87112f4ae094bbaf70830e20aa','2020-06-23 19:03:12','2020-06-23 19:03:12');
